1	// =============================================================================
2	// [VINYL ANGEL MATHEMATICAL & ULTRA HIGH-PERFORMANCE ETL ENGINE]
3	// =============================================================================
4	import { executeOrder, API_BASE } from '../../../services/api';
5	import { getRankFromScore } from '../../../utils/rank';
6	import type {
7	  Tier3StateRecord,
8	  ChannelStateRecord,
9	  Tier2EventEntry,
10	  VinylDisplayCard,
11	  PlaylistItem,
12	  ChannelOriginItem,
13	  CurlerResult,
14	  CurlerStreamEvent,
15	} from '../types';
16	
17	export const ARC_METADATA: Record<string, { title: string; emoji: string }> = {
18	  timeblock_arc0: { title: 'Arc Zero ~ Kick Starter', emoji: '🌊' },
19	  timeblock_arc1: { title: 'Arc 01 ~ Morning Star - Raye', emoji: '🚀' },
20	  timeblock_arc2: { title: 'Arc 02 ~ Battle Phase - Racheal', emoji: '⚔️' },
21	  timeblock_arc3: { title: 'Arc 03 ~ Night Hours Melody', emoji: '🌙' },
22	  timeblock_arc4: { title: 'Arc 04 ~ Sacred Pragma', emoji: '🪶' },
23	};
24	
25	interface Tier1StaticItem {
26	  title?: string;
27	  channel_name?: string;
28	  channel?: string;
29	  artist?: string;
30	  duration?: number | string;
31	}
32	
33	const tier1MemoryCache: Record<string, Tier1StaticItem> = {};
34	let cachedEligibleTier4List: VinylDisplayCard[] | null = null;
35	
36	export function invalidateVinylCache(projectId?: string) {
37	  cachedEligibleTier4List = null;
38	  if (!projectId) {
39	    for (const k in tier1MemoryCache) delete tier1MemoryCache[k];
40	  }
41	}
42	
43	export function calculateHazardLevel(record: Tier3StateRecord | ChannelStateRecord): number {
44	  const s3 = record.score_3_count.length;
45	  const s4 = record.score_4_count.length;
46	  const s5 = record.score_5_count.length;
47	  const s6 = record.score_6_count.length;
48	  const s7 = record.score_7_count.length;
49	
50	  const rawXP = 10 * s5 + 65 * s6 + 200 * s7 - 70 * s3 - 3 * s4;
51	  if (rawXP === 0) return 3.0;
52	
53	  const sgn = rawXP >= 0 ? 1 : -1;
54	  const scalingCoefficient = 5.0 / Math.log(51);
55	  const score = 3.0 + sgn * scalingCoefficient * Math.log(1 + Math.abs(rawXP) / 300);
56	
57	  return Math.round(score * 100) / 100;
58	}
59	
60	export function calculateTotalPlayed(record: Tier3StateRecord | ChannelStateRecord): number {
61	  return (
62	    record.score_3_count.length +
63	    record.score_4_count.length +
64	    record.score_5_count.length +
65	    record.score_6_count.length +
66	    record.score_7_count.length
67	  );
68	}
69	
70	export function getDominantTimeblock(record: Tier3StateRecord | ChannelStateRecord): string | null {
71	  const arcCounts = [
72	    { key: 'timeblock_arc0', count: record.timeblock_arc0 },
73	    { key: 'timeblock_arc1', count: record.timeblock_arc1 },
74	    { key: 'timeblock_arc2', count: record.timeblock_arc2 },
75	    { key: 'timeblock_arc3', count: record.timeblock_arc3 },
76	    { key: 'timeblock_arc4', count: record.timeblock_arc4 },
77	  ];
78	  arcCounts.sort((a, b) => b.count - a.count);
79	  const highest = arcCounts[0];
80	  return highest && highest.count > 0 ? ARC_METADATA[highest.key]?.title || null : null;
81	}
82	
83	function parseJsonArray(val: unknown): string[] {
84	  if (Array.isArray(val)) return val;
85	  if (typeof val === 'string' && val.trim() !== '') {
86	    try {
87	      const parsed = JSON.parse(val);
88	      return Array.isArray(parsed) ? parsed : [];
89	    } catch {
90	      return [];
91	    }
92	  }
93	  return [];
94	}
95	
96	export async function fetchChannelState(
97	  projectId: string
98	): Promise<Record<string, ChannelStateRecord>> {
99	  try {
100	    const res = await executeOrder<Record<string, Record<string, unknown>>>({
101	      project_id: projectId,
102	      tier: 'channel_state',
103	      order: { action: 'read_all' },
104	    });
105	    const rawData = res.data || {};
106	    const result: Record<string, ChannelStateRecord> = {};
107	
108	    for (const [chId, row] of Object.entries(rawData)) {
109	      result[chId] = {
110	        channel_id: chId,
111	        channel_name: (row.channel_name as string) || '',
112	        score_3_count: parseJsonArray(row.score_3_count),
113	        score_4_count: parseJsonArray(row.score_4_count),
114	        score_5_count: parseJsonArray(row.score_5_count),
115	        score_6_count: parseJsonArray(row.score_6_count),
116	        score_7_count: parseJsonArray(row.score_7_count),
117	        timeblock_arc0: Number(row.timeblock_arc0) || 0,
118	        timeblock_arc1: Number(row.timeblock_arc1) || 0,
119	        timeblock_arc2: Number(row.timeblock_arc2) || 0,
120	        timeblock_arc3: Number(row.timeblock_arc3) || 0,
121	        timeblock_arc4: Number(row.timeblock_arc4) || 0,
122	        unlock_date: (row.unlock_date as string) || null,
123	        updated_at: (row.updated_at as string) || undefined,
124	      };
125	    }
126	    return result;
127	  } catch (e) {
128	    console.warn('[Engine] Failed to fetch channel_state table:', e);
129	    return {};
130	  }
131	}
132	
133	export async function rateChannelDirect(
134	  projectId: string,
135	  channelId: string,
136	  channelName: string,
137	  action: string,
138	  timeblocks: string[] = []
139	): Promise<{ success: boolean; hazard: number; played: number; record: ChannelStateRecord }> {
140	  const currentChannels = await fetchChannelState(projectId);
141	  const chRecord: ChannelStateRecord = currentChannels[channelId] || {
142	    channel_id: channelId,
143	    channel_name: channelName,
144	    score_3_count: [],
145	    score_4_count: [],
146	    score_5_count: [],
147	    score_6_count: [],
148	    score_7_count: [],
149	    timeblock_arc0: 0,
150	    timeblock_arc1: 0,
151	    timeblock_arc2: 0,
152	    timeblock_arc3: 0,
153	    timeblock_arc4: 0,
154	    unlock_date: null,
155	  };
156	
157	  const timestampHex = Date.now().toString(16).toUpperCase();
158	  const act = action.toLowerCase().trim();
159	
160	  if (act === '3+' || act === 'cancel' || act === 'downvote') {
161	    chRecord.score_3_count.push(timestampHex);
162	  } else if (act === '4+') {
163	    chRecord.score_4_count.push(timestampHex);
164	  } else if (act === '5+' || act === 'continue') {
165	    chRecord.score_5_count.push(timestampHex);
166	  } else if (act === '6+' || act === 'upvote') {
167	    chRecord.score_6_count.push(timestampHex);
168	  } else if (act === '7+' || act === 'overflow') {
169	    chRecord.score_7_count.push(timestampHex);
170	  }
171	
172	  if (timeblocks && timeblocks.length > 0) {
173	    timeblocks.forEach((b) => {
174	      if (/arc\s*zero|kick/i.test(b)) chRecord.timeblock_arc0++;
175	      else if (/arc\s*0?1|morning/i.test(b)) chRecord.timeblock_arc1++;
176	      else if (/arc\s*0?2|battle/i.test(b)) chRecord.timeblock_arc2++;
177	      else if (/arc\s*0?3|night/i.test(b)) chRecord.timeblock_arc3++;
178	      else if (/arc\s*0?4|sacred/i.test(b)) chRecord.timeblock_arc4++;
179	    });
180	  }
181	
182	  chRecord.updated_at = new Date().toISOString();
183	
184	  // 1. Upsert into channel_state table in _3_state.db
185	  await executeOrder({
186	    project_id: projectId,
187	    tier: 'channel_state',
188	    order: {
189	      action: 'upsert',
190	      key: channelId,
191	      data: {
192	        channel_name: channelName,
193	        score_3_count: JSON.stringify(chRecord.score_3_count),
194	        score_4_count: JSON.stringify(chRecord.score_4_count),
195	        score_5_count: JSON.stringify(chRecord.score_5_count),
196	        score_6_count: JSON.stringify(chRecord.score_6_count),
197	        score_7_count: JSON.stringify(chRecord.score_7_count),
198	        timeblock_arc0: chRecord.timeblock_arc0,
199	        timeblock_arc1: chRecord.timeblock_arc1,
200	        timeblock_arc2: chRecord.timeblock_arc2,
201	        timeblock_arc3: chRecord.timeblock_arc3,
202	        timeblock_arc4: chRecord.timeblock_arc4,
203	        unlock_date: chRecord.unlock_date,
204	        updated_at: chRecord.updated_at,
205	      },
206	    },
207	  });
208	
209	  // 2. Also record to Tier 2 JSONL event buffer
210	  await executeOrder({
211	    project_id: projectId,
212	    tier: '2',
213	    order: {
214	      action: 'append',
215	      data: {
216	        id: channelId,
217	        target_type: 'channel',
218	        channel_id: channelId,
219	        channel_name: channelName,
220	        action: action,
221	        timestamp: timestampHex,
222	        timeblock: timeblocks.length === 1 ? timeblocks[0] : timeblocks.length > 1 ? timeblocks : undefined,
223	      },
224	    },
225	  });
226	
227	  const hazard = calculateHazardLevel(chRecord);
228	  const played = calculateTotalPlayed(chRecord);
229	
230	  return { success: true, hazard, played, record: chRecord };
231	}
232	
233	export async function fetchEligibleTier4List(
234	  projectId: string,
235	  forceRefresh = false
236	): Promise<VinylDisplayCard[]> {
237	  if (!forceRefresh && cachedEligibleTier4List) {
238	    return cachedEligibleTier4List;
239	  }
240	
241	  const t4Res = await executeOrder<Record<string, Record<string, unknown>>>({
242	    project_id: projectId,
243	    tier: '4',
244	    order: { action: 'read_all' },
245	  });
246	  const t4Data = t4Res.data || {};
247	
248	  const list: VinylDisplayCard[] = [];
249	  let indexCounter = 1;
250	
251	  for (const [id, rawT4] of Object.entries(t4Data)) {
252	    const t4Item = (rawT4 as Record<string, unknown>) || {};
253	    const rawHazard = t4Item.hazard_level;
254	    const hazard =
255	      rawHazard !== undefined && rawHazard !== null && !isNaN(Number(rawHazard))
256	        ? Number(rawHazard)
257	        : 3.0;
258	
259	    if (hazard <= 3.0) continue;
260	
261	    const rawPlayed = t4Item.played;
262	    const played =
263	      rawPlayed !== undefined && rawPlayed !== null && !isNaN(Number(rawPlayed))
264	        ? Number(rawPlayed)
265	        : 0;
266	
267	    list.push({
268	      id,
269	      dbIndex: indexCounter++,
270	      title: `Track ${id}`,
271	      channel: '',
272	      duration: null,
273	      hazard_level: hazard,
274	      played,
275	      timeblock: (t4Item.timeblock as string) || null,
276	      unlock_date: (t4Item.unlock_date as string) || null,
277	      rankCategory: getRankFromScore(hazard),
278	    });
279	  }
280	
281	  cachedEligibleTier4List = list;
282	  return list;
283	}
284	
285	// =============================================================================
286	// [SINGLE-REQUEST BATCH READ FOR 16 PAGE ITEMS]
287	// =============================================================================
288	export async function resolvePageMetadataOnDemand(
289	  projectId: string,
290	  pageTracks: VinylDisplayCard[]
291	): Promise<VinylDisplayCard[]> {
292	  if (pageTracks.length === 0) return [];
293	
294	  const missingIds = pageTracks
295	    .map((t) => t.id)
296	    .filter((id) => !tier1MemoryCache[id]);
297	
298	  if (missingIds.length > 0) {
299	    try {
300	      const res = await executeOrder<Record<string, Tier1StaticItem>>({
301	        project_id: projectId,
302	        tier: '1',
303	        order: { action: 'batch_read', data: missingIds },
304	      });
305	      const dataMap = res.data || {};
306	      for (const [id, staticInfo] of Object.entries(dataMap)) {
307	        tier1MemoryCache[id] = staticInfo;
308	      }
309	    } catch (e) {
310	      console.warn(`[LazyTier1 Batch] Lỗi tải batch ${missingIds.length} items:`, e);
311	    }
312	  }
313	
314	  return pageTracks.map((item) => {
