let isDestroyed = false;
let pollInterval: any = null;

const mountPlayer = () => {
  const container = document.getElementById('vinyl-yt-player');
  if (!container || isDestroyed) return;

  if (playerRef.current) {
    const targetId = pendingVideoIdRef.current || currentTrackRef.current?.id;
    if (targetId && isPlayerReadyRef.current) {
      syncVideoToPlayer(targetId);
    }
    return;
  }

  if (!window.YT || !window.YT.Player) {
    return;
  }

  const initialVideoId =
    pendingVideoIdRef.current ||
    currentTrackRef.current?.id ||
    playlistRef.current[currentIndexRef.current]?.id ||
    '';

  try {
    playerRef.current = new window.YT.Player('vinyl-yt-player', {
      host: 'https://www.youtube-nocookie.com',
      height: '100%',
      width: '100%',
      videoId: initialVideoId || undefined,
      playerVars: {
        autoplay: 1,
        controls: 1,
        modestbranding: 1,
        rel: 0,
        enablejsapi: 1,
        origin: window.location.origin,
      },
      events: {
        onReady: (event: any) => {
          if (isDestroyed) return;
          isPlayerReadyRef.current = true;

          // Immediately synchronize to the authoritative currentTrack target
          const targetId =
            pendingVideoIdRef.current ||
            currentTrackRef.current?.id ||
            playlistRef.current[currentIndexRef.current]?.id;

          if (targetId) {
            currentlyLoadedVideoIdRef.current = targetId;
            pendingVideoIdRef.current = null;
            try {
              event.target.loadVideoById({
                videoId: String(targetId).trim(),
                startSeconds: 0,
              });
              event.target.playVideo();
            } catch (e) {
              console.warn('[YouTube Player] onReady load error:', e);
            }
          } else if (initialVideoId) {
            currentlyLoadedVideoIdRef.current = initialVideoId;
            try {
              event.target.playVideo();
            } catch (_) {}
          }
        },
        onStateChange: (event: any) => {
          if (isDestroyed) return;

          // Self-healing watchdog: check playing video ID against currentTrack
          if (event.data === window.YT.PlayerState.PLAYING) {
            const playingId = event.target?.getVideoData?.()?.video_id;
            const expectedTrack = currentTrackRef.current;
            if (playingId && expectedTrack?.id && playingId !== expectedTrack.id) {
              console.warn(
                `[YouTube Watchdog] Desync detected (playing ${playingId} vs expected ${expectedTrack.id}). Resyncing...`

