def _build_hazard_filter_clause(conn: sqlite3.Connection, app_data_dir: Path, hazard_cap: Any) -> Optional[str]:
    """
    Constructs an ultra-fast cross-database SQLite filter clause for hazard level & sovereign hazard rank.
    Attaches _4_display.db (t4_db) and _3_state.db (t3_db) to query across tables without memory overhead.
    """
    if hazard_cap is None:
        return None
    h_str = str(hazard_cap).strip().lower()
    if h_str in ["none", "all", "inf", "", "all tracks"]:
        return None

    t4_file = app_data_dir / "_4_display.db"
    t3_file = app_data_dir / "_3_state.db"
    if not t4_file.exists():
        return None

    cursor = conn.cursor()
    cursor.execute("PRAGMA database_list")
    attached = {row[1] for row in cursor.fetchall()}
    if "t4_db" not in attached:
        cursor.execute("ATTACH DATABASE ? AS t4_db", (str(t4_file),))
    if t3_file.exists() and "t3_db" not in attached:
        cursor.execute("ATTACH DATABASE ? AS t3_db", (str(t3_file),))

    cursor.execute("PRAGMA database_list")
    attached = {row[1] for row in cursor.fetchall()}
    has_t3 = "t3_db" in attached

    # 1. Option "7+" (Hazard >= 7.0 or hazard_rank >= 7)
    if h_str in ["7+", "7_plus", "7", ">=7", "7.0+"]:
        if has_t3:
            return "id IN (SELECT id FROM t4_db.tier_4_data WHERE hazard_level >= 7.0 UNION SELECT id FROM t3_db.tier_3_data WHERE hazard_rank >= 7)"
        return "id IN (SELECT id FROM t4_db.tier_4_data WHERE hazard_level >= 7.0)"

    # 2. Option "6+" (Hazard >= 6.0 or hazard_rank >= 6)
    if h_str in ["6+", "6_plus", "6", ">=6", "6.0+"]:
        if has_t3:
            return "id IN (SELECT id FROM t4_db.tier_4_data WHERE hazard_level >= 6.0 UNION SELECT id FROM t3_db.tier_3_data WHERE hazard_rank >= 6)"
        return "id IN (SELECT id FROM t4_db.tier_4_data WHERE hazard_level >= 6.0)"

    # 3. Option "3.2 to under 6" (3.2 <= Hazard < 6.0)
    if h_str in ["3.2 to under 6", "3.2_to_under_6", "3.2-6.0", "3.2_6.0", "mid"]:
        if has_t3:
            return "id IN (SELECT id FROM t4_db.tier_4_data WHERE hazard_level >= 3.2 AND hazard_level < 6.0 UNION SELECT id FROM t3_db.tier_3_data WHERE hazard_rank >= 4 AND hazard_rank < 6)"
        return "id IN (SELECT id FROM t4_db.tier_4_data WHERE hazard_level >= 3.2 AND hazard_level < 6.0)"

    # 4. Option "under 3.2" (Hazard < 3.2 or unrated)
    if h_str in ["under 3.2", "under_3.2", "<3.2", "3.2", "calm"]:
        if has_t3:
            return "id NOT IN (SELECT id FROM t4_db.tier_4_data WHERE hazard_level >= 3.2 UNION SELECT id FROM t3_db.tier_3_data WHERE hazard_rank >= 4)"
        return "id NOT IN (SELECT id FROM t4_db.tier_4_data WHERE hazard_level >= 3.2)"

    # 5. Generic float threshold fallback: under <cap_val>
    try:
        cap_val = float(h_str)
        return f"id NOT IN (SELECT id FROM t4_db.tier_4_data WHERE hazard_level > {cap_val})"
    except ValueError:
        return None

