export function calculateHazardLevel(record: Tier3StateRecord | ChannelStateRecord): number {
  const rank = record.hazard_rank;
  if (!rank || rank < 3 || rank > 7) {
    return 3.0; // Unranked baseline
  }

  const s5 = record.score_5_count?.length || 0;
  const s6 = record.score_6_count?.length || 0;
  const s7 = record.score_7_count?.length || 0;

  // Sovereign calibration: 25 of 7+ (4pts), 50 of 6+ (2pts), or 100 of 5+ (1pt) to reach 8.0
  const S = 4 * s7 + 2 * s6 + 1 * s5;

  const base = rank - 0.5;
  const k = (8.5 - rank) / 100.0;

  const score = base + k * S;
  return Math.round(Math.min(8.5, Math.max(1.0, score)) * 100) / 100;
}
```

---

### 2. Concrete Verification Matrix

Every mathematical condition specified has been confirmed:

| Hazard Rank $r$ | Baseline ($r - 0.5$) | $k$ Multiplier | 25 Crowns (7+) | 50 Blazes (6+) | 100 Completions (5+) |
| :---: | :---: | :---: | :---: | :---: | :---: |
| **Rank 7** | **6.50** | **0.015** | **8.00** | **8.00** | **8.00** |
| **Rank 6** | **5.50** | **0.025** | **8.00** | **8.00** | **8.00** |
| **Rank 5** | **4.50** | **0.035** | **8.00** | **8.00** | **8.00** |
| **Rank 4** | **3.50** | **0.045** | **8.00** | **8.00** | **8.00** |
| **Rank 3** | **2.50** | **0.055** | **8.00** | **8.00** | **8.00** |
| *Unranked* | **3.00** | — | — | — | — |

---

### 3. Real-Time Gameplay Projection

1. **Immediate Tier 3 & Tier 4 Synchronization**:
   - In `updateTrackHazardRank()`: When you click any rank (3 to 7) on the gameplay tab, it:
     - Persists `hazard_rank` to `_3_state.db` (Tier 3).
     - Instantly evaluates the formula ($r - 0.5 + k \times S$) and projects the resulting `hazard_level` directly into `_4_display.db` (Tier 4).
     - Optimistically updates the UI badge, toast, and player telemetry in real-time.
2. **Selective Tier 4 Pipeline**:
   - In `syncTier3ToTier4()`: Only tracks with an assigned `hazard_rank` are projected into `_4_display.db`. 
   - All unranked songs remain cleanly in `_1_static.db` and are treated as 3.00, keeping `_4_display.db` lean, fast, and completely in sync with your sovereign designations.

Everything is compiled with zero diagnostics and ready in the live app, Manager!

