            },
          }));
          setPlaylist((prev) =>
            prev.map((t) => (t.id === trackId ? { ...t, hazard_rank: rank } : t))
          );
        }
      })
      .catch(() => {});
  }
}, [currentTrack?.id, targetProjectId, displayStats]);

