    showToast(`🚫 Blacklisted & Logged BLOCK${arcSuffix}${rankSuffix} (+3 Discs)`, 'warn');
  } else {
    showToast(`✨ Logged ${action.toUpperCase()}${arcSuffix}${rankSuffix} (+3 Discs)`, 'success');
  }

  // Check if earlier outbox items need flushing
  const pendingOutbox = useVinylStore.getState().offlineOutbox || [];
  if (pendingOutbox.length > 0) {
    flushQueuedEvents();
  }
} catch (err: any) {
  // 3. Fallback: Save to Offline Outbox safely
  enqueueOfflineEvent(payloadData);
  showToast(
    `📦 Offline Outbox: Queued ${action.toUpperCase()}${arcSuffix}${rankSuffix} (auto-flushes to _2_events.jsonl on reconnect) (+3 💿)`,
    'warn'
  );
} finally {
  setSelectedArcs([]);
  setSelectedScore('');
  selectedScoreRef.current = '';
  setStagedHazardRank(null);
  stagedHazardRankRef.current = null;
  if (isMountedRef.current) setIsLogging(false);
}

