// Sovereign Hazard Rank Assignment (3 to 7)
const handleAssignHazardRank = async (rank: number) => {
  const activeTrack = currentTrackRef.current;
  if (!activeTrack || !activeTrack.id || isAssigningRank) return;
  const trackId = String(activeTrack.id).trim();

  setIsAssigningRank(true);
  try {
    const res = await updateTrackHazardRank(targetProjectId, trackId, rank);
    const newHazard = res?.newHazard ?? (rank - 0.5);

    // Optimistically update displayStats
    setDisplayStats((prev) => {
      const cur = prev[trackId] || { played: 0, hazard_level: 3.0, timeblock: null, unlock_date: null };
      return {
        ...prev,
        [trackId]: {
          ...cur,
          hazard_rank: rank,
          hazard_level: newHazard,
        },
      };
    });

    // Optimistically update playlist item
    setPlaylist((prev) =>
      prev.map((t) => (t.id === trackId ? { ...t, hazard_rank: rank, hazard_level: newHazard } : t))
    );

    showToast(`👑 Assigned Sovereign Rank ${rank} (Hazard: ${newHazard.toFixed(2)}) to "${activeTrack.title}"`, 'success');
  } catch (err) {
    showToast(`Failed to assign Hazard Rank ${rank}`, 'error');
  } finally {
    if (isMountedRef.current) setIsAssigningRank(false);
  }
};

// Automatically synchronize hazard_rank from _3_state.db if not yet in displayStats
useEffect(() => {
  const activeTrack = currentTrack;
  if (!activeTrack || !activeTrack.id) return;
  const trackId = String(activeTrack.id).trim();

  if (displayStats[trackId]?.hazard_rank === undefined && activeTrack.hazard_rank === undefined) {
    executeOrder<Record<string, unknown>>({
      project_id: targetProjectId,
      tier: '3',
      order: { action: 'read_key', key: trackId },
    })
      .then((res) => {
        if (res.data && res.data.hazard_rank !== undefined && res.data.hazard_rank !== null) {
          const rank = Number(res.data.hazard_rank);
          setDisplayStats((prev) => ({
            ...prev,
            [trackId]: {
              ...(prev[trackId] || { played: 0, hazard_level: 3.0, timeblock: null, unlock_date: null }),
              hazard_rank: rank,
            },
          }));

