const replenishBufferIfNeeded = useCallback(async () => {
  if (isFetchingMoreRef.current || playlistRef.current.length >= 15) return;

  isFetchingMoreRef.current = true;
  try {
    const moreTracks = await fetchMoreSampledTracks(
      targetProjectId,
      50,
      selectedChannelRef.current,
      hazardCapRef.current,
      excludedChannelsRef.current
    );
    if (!isMountedRef.current) return;

    const newUniqueTracks = moreTracks.filter((t) => !seenIdsRef.current.has(t.id));
