  const existingRank = displayStats[trackId]?.hazard_rank ?? activeTrack.hazard_rank ?? null;
  setStagedHazardRank(existingRank);

  if (displayStats[trackId]?.hazard_rank === undefined && activeTrack.hazard_rank === undefined) {
