          setPlaylist((prev) =>
            prev.map((t) => (t.id === trackId ? { ...t, hazard_rank: rank } : t))
          );
          setStagedHazardRank((prev) => prev ?? rank);
        }
      })
      .catch(() => {});
  }
}, [currentTrack?.id, targetProjectId]);

