// Start Ingestion Streaming
const handleStartIngestion = async () => {
  if (isRunning) return;

  if (ingestionMode === 'single') {
    const cleanUrl = singleUrlInput.trim();
    if (!cleanUrl) {
      showToast('Please enter a YouTube video or playlist link', 'warn');
      return;
    }
  } else if (playlists.length === 0) {
    showToast('No playlists configured in playlists.txt', 'warn');
    return;
  }

  const isSingle = ingestionMode === 'single';
  const targetUrls = isSingle ? [singleUrlInput.trim()] : undefined;

  setIsRunning(true);
  setCurrentProgress({ current: 0, total: isSingle ? 1 : playlists.length });
  setTotalScanned(0);
  setTotalNewAdded(0);
  setTotalGreen(0);
  setTotalYellow(0);
  setTotalRed(0);
  setFinalReport([]);

  const controller = new AbortController();
  abortControllerRef.current = controller;

  addLog(
    'INIT',
    isSingle
      ? `Starting Single Ingestion for: ${singleUrlInput.trim()}`
      : `Starting 3-Tier Diagnostic Playlist Ingestion Pipeline...`,
    'info'
  );

  const options: any = {};
  if (targetUrls) {
    options.urls = targetUrls;
  } else if (executionLimit === 'sample') {
    options.max_playlists = 4;
    options.max_per_playlist = 10;
  }

